export const NASA_CDF_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/nasa-cdf-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getNasaCdfStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(NASA_CDF_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
